INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ultimate', 'adj.', '/ˈʌltɪmət/', '终极的;最好的;最重要的', 'Winning the title was the ultimate dream of every player on the team.', '夺冠是队里每名球员的终极梦想。', 'Sports', 1, 0, 'senior', 'wordlist', 'required2', 'U4', 'the ultimate goal', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tough', 'adj.', '/tʌf/', '艰难的;棘手的;坚韧的;能吃苦的', 'Their next opponent is a tough team that never gives up.', '他们的下一个对手是一支永不放弃的强队。', 'Sports', 2, 0, 'senior', 'wordlist', 'required2', 'U4', 'a tough competitor', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'competitor', 'n.', '/kəmˈpetɪtə(r)/', '竞争者;比赛者;对手', 'Every competitor in the race wanted to reach the line first.', '比赛中每个选手都想第一个冲过终点线。', 'Sports', 3, 0, 'senior', 'wordlist', 'required2', 'U4', 'a strong competitor', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'million', 'n.', '/ˈmɪljən/', '一百万;百万', 'Millions of people watched the final match on television.', '数百万人在电视上观看了那场决赛。', 'Sports', 4, 0, 'senior', 'wordlist', 'required2', 'U4', 'millions of fans', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'bend', 'v.', '/bend/', '使弯曲;(使)倾斜', 'Beckham could bend the ball around the wall and into the net.', '贝克汉姆能让球绕过人墙弯进球网。', 'Sports', 5, 0, 'senior', 'wordlist', 'required2', 'U4', 'bend the ball', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'net', 'n.', '/net/', '球门网;网;网状物', 'She hit the ball hard, and it flew straight into the net.', '她用力一射,球径直飞进了球网。', 'Sports', 6, 0, 'senior', 'wordlist', 'required2', 'U4', 'into the net', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'goal', 'n.', '/ɡəʊl/', '射门;进球;球门;目标', 'He scored the winning goal in the last minute of the game.', '他在比赛最后一分钟攻入了制胜进球。', 'Sports', 7, 0, 'senior', 'wordlist', 'required2', 'U4', 'score a goal', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'relief', 'n.', '/rɪˈliːf/', '宽慰;轻松;解脱', 'When the final whistle blew, the players felt great relief.', '终场哨声响起时,球员们感到极大的宽慰。', 'Sports', 8, 0, 'senior', 'wordlist', 'required2', 'U4', 'a sense of relief', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'scream', 'v.', '/skriːm/', '尖叫;高声喊', 'The whole team began to scream with joy after the goal.', '进球之后全队都开始欢呼尖叫。', 'Sports', 9, 0, 'senior', 'wordlist', 'required2', 'U4', 'scream with joy', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'draw', 'n.', '/drɔː/', '平局;和局;抽签', 'The match ended in a draw, so the teams went to penalties.', '比赛打成平局,两队便进入点球大战。', 'Sports', 10, 0, 'senior', 'wordlist', 'required2', 'U4', 'end in a draw', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'friendly', 'n.', '/ˈfrendli/', '友谊赛;adj. 友好的', 'Before the season, the two clubs played a friendly for practice.', '赛季之前,两家俱乐部踢了一场友谊赛练兵。', 'Sports', 11, 0, 'senior', 'wordlist', 'required2', 'U4', 'play a friendly', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'roll', 'v.', '/rəʊl/', '(使)滚动;翻滚', 'She rolled the ball smoothly into the corner of the net.', '她把球平稳地滚进了球网的角落。', 'Sports', 12, 0, 'senior', 'wordlist', 'required2', 'U4', 'roll the ball', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'breath', 'n.', '/breθ/', '呼吸;一次吸入的空气', 'She took a deep breath before stepping up to take the penalty.', '上前主罚点球前,她深吸了一口气。', 'Sports', 13, 0, 'senior', 'wordlist', 'required2', 'U4', 'take a deep breath', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'calm', 'v./adj.', '/kɑːm/', '(使)平静;镇静的;沉着的', 'He tried to calm himself down before the most important shot.', '在最关键的一射之前,他努力让自己镇定下来。', 'Sports', 14, 0, 'senior', 'wordlist', 'required2', 'U4', 'calm down', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'roar', 'n.', '/rɔː(r)/', '咆哮;吼叫;轰鸣', 'A loud roar around the stadium told her that the goal had gone in.', '体育场里一声巨大的轰鸣告诉她进球了。', 'Sports', 15, 0, 'senior', 'wordlist', 'required2', 'U4', 'a loud roar', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stadium', 'n.', '/ˈsteɪdiəm/', '体育场;运动场', 'Thousands of fans filled the stadium to watch the big match.', '成千上万的球迷涌入体育场观看这场大赛。', 'Sports', 16, 0, 'senior', 'wordlist', 'required2', 'U4', 'a football stadium', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'spot', 'n.', '/spɒt/', '地点;场所;位置', 'He placed the ball on the spot and looked up at the goal.', '他把球放在点球点上,抬头望向球门。', 'Sports', 17, 0, 'senior', 'wordlist', 'required2', 'U4', 'the penalty spot', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'incredibly', 'adv.', '/ɪnˈkredəbli/', '极其;难以置信地', 'By the end of the game she was incredibly tired but very happy.', '比赛结束时她累极了,却非常开心。', 'Sports', 18, 0, 'senior', 'wordlist', 'required2', 'U4', 'incredibly tired', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'bounce', 'v.', '/baʊns/', '(使)弹起;弹跳', 'The ball hit the crossbar and bounced away into the crowd.', '球打在横梁上,弹开飞进了人群。', 'Sports', 19, 0, 'senior', 'wordlist', 'required2', 'U4', 'bounce away', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'crowd', 'n.', '/kraʊd/', '人群;观众', 'A huge crowd cheered loudly when the home team scored.', '主队进球时,一大群观众大声欢呼。', 'Sports', 20, 0, 'senior', 'wordlist', 'required2', 'U4', 'a huge crowd', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'judge', 'n.', '/dʒʌdʒ/', '裁判员;评判员;法官', 'In wushu, the judges give points for each athlete''s movements.', '在武术比赛中,裁判为每位选手的动作打分。', 'Sports', 21, 0, 'senior', 'wordlist', 'required2', 'U4', 'the judges'' points', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'admire', 'v.', '/ədˈmaɪə(r)/', '钦佩;赞赏;仰慕', 'Young fans admire the players who train hard and never give up.', '年轻球迷仰慕那些刻苦训练、永不放弃的球员。', 'Sports', 22, 0, 'senior', 'wordlist', 'required2', 'U4', 'admire a player', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'realistic', 'adj.', '/ˌrɪəˈlɪstɪk/', '现实的;实事求是的', 'He has to be realistic about how far he can go in the sport.', '他得现实地看待自己在这项运动上能走多远。', 'Sports', 23, 0, 'senior', 'wordlist', 'required2', 'U4', 'be realistic', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'professional', 'n./adj.', '/prəˈfeʃənl/', '职业运动员;专业人士;职业的', 'The top competitors are professionals who train several hours a day.', '顶尖选手都是每天训练数小时的职业运动员。', 'Sports', 24, 0, 'senior', 'wordlist', 'required2', 'U4', 'a professional athlete', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'title', 'n.', '/ˈtaɪtl/', '冠军;头衔;(书等的)名称', 'The team won the title for the third year in a row.', '这支球队连续第三年夺得冠军。', 'Sports', 25, 0, 'senior', 'wordlist', 'required2', 'U4', 'win the title', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'athlete', 'n.', '/ˈæθliːt/', '运动员', 'Every great athlete knows that hard training comes before success.', '每位伟大的运动员都明白,刻苦训练先于成功。', 'Sports', 26, 0, 'senior', 'wordlist', 'required2', 'U4', 'a young athlete', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'Olympic', 'adj.', '/əˈlɪmpɪk/', '奥林匹克的;奥运会的', 'Her dream is to take part in the Olympic Games one day.', '她的梦想是有一天能参加奥运会。', 'Sports', 27, 0, 'senior', 'wordlist', 'required2', 'U4', 'the Olympic Games', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'spectator', 'n.', '/spekˈteɪtə(r)/', '观看者;观众', 'The spectators held their breath as the final point was played.', '决胜分上演时,观众们都屏住了呼吸。', 'Sports', 28, 0, 'senior', 'wordlist', 'required2', 'U4', 'thousands of spectators', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'champion', 'n.', '/ˈtʃæmpiən/', '冠军;优胜者', 'After years of training, she became the world champion in her event.', '经过多年训练,她成为本项目的世界冠军。', 'Sports', 29, 0, 'senior', 'wordlist', 'required2', 'U4', 'the world champion', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'victory', 'n.', '/ˈvɪktəri/', '胜利;获胜', 'Working together, the players led their team to a great victory.', '通过齐心协力,球员们带领球队取得了大胜。', 'Sports', 30, 0, 'senior', 'wordlist', 'required2', 'U4', 'lead to victory', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'defend', 'v.', '/dɪˈfend/', '防守;保卫;为……辩护', 'The goalkeeper bravely defended the goal until the final whistle.', '门将一直勇敢地守卫球门,直到终场哨响。', 'Sports', 31, 0, 'senior', 'wordlist', 'required2', 'U4', 'defend the goal', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'score', 'v./n.', '/skɔː(r)/', '得分;进球;比分', 'She scored the winning point and the crowd went wild.', '她拿下制胜的一分,观众都疯狂了。', 'Sports', 32, 0, 'senior', 'wordlist', 'required2', 'U4', 'score a point', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pass', 'v.', '/pɑːs/', '传(球);经过;通过', 'He passed the ball forward into space for his teammate to run onto.', '他把球向前传到空当,让队友插上接应。', 'Sports', 33, 0, 'senior', 'wordlist', 'required2', 'U4', 'pass the ball', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'shoot', 'v.', '/ʃuːt/', '射门;投篮;射击', 'The striker is preparing to shoot at the goal from outside the box.', '前锋正准备在禁区外起脚射门。', 'Sports', 34, 0, 'senior', 'wordlist', 'required2', 'U4', 'shoot at goal', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'match', 'n.', '/mætʃ/', '比赛;对手;相配的人/物', 'It was a close match, and neither team scored until the very end.', '这是场势均力敌的比赛,直到最后双方才有进球。', 'Sports', 35, 0, 'senior', 'wordlist', 'required2', 'U4', 'a close match', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'effort', 'n.', '/ˈefət/', '努力;气力', 'She made a superhuman effort and ran towards the ball.', '她用尽全力,朝着球冲了过去。', 'Sports', 36, 0, 'senior', 'wordlist', 'required2', 'U4', 'make an effort', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'nervous', 'adj.', '/ˈnɜːvəs/', '紧张的;焦虑的', 'Before the penalty, Tina looked very nervous indeed.', '在罚点球之前,蒂娜看上去确实非常紧张。', 'Sports', 37, 0, 'senior', 'wordlist', 'required2', 'U4', 'feel nervous', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'encourage', 'v.', '/ɪnˈkʌrɪdʒ/', '鼓励;激励', 'Behind her she could hear the girls yelling encouragement.', '她身后能听见女孩们大声喊着为她鼓劲。', 'Sports', 38, 0, 'senior', 'wordlist', 'required2', 'U4', 'encourage the team', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'coach', 'n.', '/kəʊtʃ/', '教练;指导', 'The coach gave the players a quick pep talk before the penalties.', '罚点球前,教练给球员们做了简短的动员。', 'Sports', 39, 0, 'senior', 'wordlist', 'required2', 'U4', 'the team coach', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fan', 'n.', '/fæn/', '球迷;爱好者;粉丝', 'Loyal fans stayed in the rain to support their favourite team.', '忠实的球迷冒雨留下来支持自己喜爱的球队。', 'Sports', 40, 0, 'senior', 'wordlist', 'required2', 'U4', 'a loyal fan', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'exhausted', 'adj.', '/ɪɡˈzɔːstɪd/', '筋疲力尽的;疲惫不堪的', 'By the end of the match every player was completely exhausted.', '比赛结束时每名球员都筋疲力尽。', 'Sports', 41, 0, 'senior', 'wordlist', 'required2', 'U4', 'feel exhausted', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'skill', 'n.', '/skɪl/', '技能;技巧', 'He practised every day to improve his basketball skills.', '他每天练习以提高自己的篮球技巧。', 'Sports', 42, 0, 'senior', 'wordlist', 'required2', 'U4', 'improve one''s skills', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'train', 'v.', '/treɪn/', '训练;锻炼', 'Having trained hard all winter, the team was ready for the season.', '整个冬天刻苦训练之后,球队为新赛季做好了准备。', 'Sports', 43, 0, 'senior', 'wordlist', 'required2', 'U4', 'train hard', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'whistle', 'n.', '/ˈwɪsl/', '哨子;哨声', 'The referee blew the whistle to start the second half.', '裁判吹哨开始下半场比赛。', 'Sports', 44, 0, 'senior', 'wordlist', 'required2', 'U4', 'blow the whistle', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'celebrate', 'v.', '/ˈselɪbreɪt/', '庆祝;庆贺', 'The players ran together to celebrate the late winning goal.', '球员们一起奔跑,庆祝那粒压哨制胜球。', 'Sports', 45, 0, 'senior', 'wordlist', 'required2', 'U4', 'celebrate the win', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'support', 'v./n.', '/səˈpɔːt/', '支持;支撑;拥护', 'Thousands of spectators came to support their home team.', '成千上万的观众前来支持主队。', 'Sports', 46, 0, 'senior', 'wordlist', 'required2', 'U4', 'support a team', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u4.01', '①-ing 作状语(主动:表时间/原因/结果/伴随)', 'A2', 10, '上外版必修第二册 U4 — 当分词的逻辑主语(=主句主语)主动发出该动作时,用 -ing 形式作状语,表示时间、原因、结果或伴随。如 Running fast, he won;Having trained hard, she won the title。', 1, 'required2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u4.02', '②-ed 作状语(被动/状态)', 'A2', 10, '上外版必修第二册 U4 — 当分词的逻辑主语(=主句主语)承受该动作、或处于被动状态时,用 -ed 形式作状语。如 Encouraged by the fans, he played on;Seen from the stand, the players looked tiny。', 2, 'required2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('s2u4.03', '③分词逻辑主语一致 + -ing 还是 -ed 的主被动辨析', 'A2', 10, '上外版必修第二册 U4 — 分词的逻辑主语必须就是主句主语;再看主语与该动作是主动还是被动:主语主动做→ -ing,主语被动受→ -ed。与连词/独立结构辨析一并考查。', 3, 'required2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ fast down the wing, he passed the ball into the net.', 'Running', 'Run', 'To run', 'Ran', 'A', 'he 主动 run,-ing 作伴随/时间状语 → Running。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ hard all winter, the team was ready for the new season.', 'To train', 'Having trained', 'Trained', 'Train', 'B', 'the team 主动完成训练且先于主句 → 完成式主动 Having trained。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), 'She ran towards the ball, ____ to score the winning goal.', 'hope', 'hoped', 'hoping', 'to hope', 'C', 'she 主动 hope,-ing 作伴随状语 → hoping。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ deep breaths, the player tried to calm herself down.', 'Taken', 'To take', 'Take', 'Taking', 'D', 'the player 主动 take breaths → Taking。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ that he was the last to shoot, Joe stepped up bravely.', 'Knowing', 'Know', 'Known', 'To know', 'A', 'Joe 主动 know,表原因 → Knowing。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), 'The crowd jumped up, ____ with joy as the ball hit the net.', 'screamed', 'screaming', 'to scream', 'scream', 'B', 'the crowd 主动 scream,伴随状语 → screaming。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ harder than anyone else, she finally won the title.', 'Train', 'Trained', 'Training', 'To train', 'C', 'she 主动 train,表原因 → Training。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), 'He left the field early, ____ that he had missed the penalty.', 'regret', 'regretted', 'to regret', 'regretting', 'D', 'he 主动 regret,伴随状语 → regretting。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ up at the goal, the striker decided where to shoot.', 'Looking', 'Looked', 'Look', 'To look', 'A', 'the striker 主动 look up → Looking。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ for the home team all night, the fans went home happy.', 'Cheer', 'Cheering', 'Cheered', 'To cheer', 'B', 'the fans 主动 cheer,表时间/原因 → Cheering。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), 'The goalkeeper dived to the left, ____ the ball with one hand.', 'stopped', 'to stop', 'stopping', 'stop', 'C', 'the goalkeeper 主动 stop the ball,结果状语 → stopping。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ the ball forward, Jules ran on to it and scored.', 'Hit', 'To hit', 'Been hitting', 'Hitting', 'D', 'Jules(主语)主动 hit,表时间/伴随 → Hitting。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ all his energy, the boxer could hardly raise his arms.', 'Using up', 'Used up', 'Use up', 'To use up', 'A', 'the boxer 主动 use up energy,表原因 → Using up。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), 'The team trained every day, ____ to reach the final.', 'hope', 'hoping', 'hoped', 'to hoping', 'B', 'the team 主动 hope,伴随状语 → hoping。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ the whistle, the referee ended the first half.', 'Blown', 'Blow', 'Blowing', 'To blowing', 'C', 'the referee 主动 blow the whistle,表时间 → Blowing。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ the goal, she turned and ran to hug her teammates.', 'Score', 'Scored', 'To score', 'Having scored', 'D', 'she 主动完成 score 且先于主句 → Having scored。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), 'He jumped on Jules, ____ loudly with the rest of the team.', 'celebrating', 'celebrated', 'to celebrate', 'celebrate', 'A', 'he 主动 celebrate,伴随状语 → celebrating。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ that the score was level, both coaches stayed calm.', 'See', 'Seeing', 'Seen', 'To see', 'B', 'both coaches 主动 see,表原因 → Seeing。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), 'The young athlete kept practising, ____ to play for his country.', 'dreamed', 'dream', 'dreaming', 'to dreaming', 'C', 'the athlete 主动 dream,伴随状语 → dreaming。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.01'), '____ the crossbar, the ball bounced away into the crowd.', 'Hit', 'Been hit', 'To hit', 'Hitting', 'D', 'the ball 主动 hit the crossbar(球撞到横梁是主动动作)→ Hitting。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ by the cheering fans, the players kept fighting to the end.', 'Encouraged', 'Encourage', 'Encouraging', 'To encourage', 'A', 'players 被 fans 鼓舞,被动 → Encouraged。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ from the top of the stand, the players looked very small.', 'Seeing', 'Seen', 'See', 'To see', 'B', 'the players 被看,被动 → Seen。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ in the final minute, the home team lost the match.', 'Beating', 'Beat', 'Beaten', 'To beat', 'C', 'the team 被打败,被动 → Beaten。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), 'The boxer played on, ____ by the noise of the crowd.', 'exciting', 'excite', 'to excite', 'excited', 'D', 'the boxer 被人群的喧闹激起(感受被动)→ excited。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ to take the last penalty, Jess walked slowly to the spot.', 'Chosen', 'Choosing', 'Choose', 'To choose', 'A', 'Jess 被选中,被动 → Chosen。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ by years of hard training, she finally won the title.', 'Prepare', 'Prepared', 'Preparing', 'To prepare', 'B', 'she 被多年训练所造就/准备,被动 → Prepared。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), 'The injured player left the pitch, ____ by two teammates.', 'helping', 'help', 'helped', 'to help', 'C', 'the player 被队友扶,被动 → helped。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ in bright team colours, the fans filled the whole stand.', 'Dress', 'Dressing', 'To dress', 'Dressed', 'D', 'the fans 处于''穿着''状态,被动/状态 → Dressed。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ off the team, the boy made up his mind to train harder.', 'Left', 'Leaving', 'Leave', 'To leave', 'A', 'the boy 被排除在队伍之外,被动 → Left。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), 'The goal was given, ____ by the referee after a quick check.', 'allow', 'allowed', 'allowing', 'to allow', 'B', 'the goal 被判有效,被动 → allowed。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ by his coach''s words, he stepped up with new confidence.', 'Inspiring', 'Inspire', 'Inspired', 'To inspire', 'C', 'he 被教练的话所激励,被动 → Inspired。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ for the wushu team, Leo flew to Europe for the games.', 'Selecting', 'Select', 'To select', 'Selected', 'D', 'Leo 被选入队,被动 → Selected。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), 'The ball, ____ hard by the striker, flew straight into the net.', 'hit', 'hitting', 'to hit', 'hits', 'A', 'the ball 被前锋大力踢,被动 → hit。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ by the loud roar, the young player nearly lost his focus.', 'Shock', 'Shocked', 'Shocking', 'To shock', 'B', 'the player 被吼声震惊,被动 → Shocked。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ in the museum, the old medals tell the story of past wins.', 'Keeping', 'Keep', 'Kept', 'To keep', 'C', 'the medals 被保存,被动 → Kept。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), 'The team played their best, ____ by thousands of home fans.', 'supporting', 'support', 'to support', 'supported', 'D', 'the team 被主场球迷支持,被动 → supported。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ to play in the rain, the children still enjoyed the game.', 'Forced', 'Forcing', 'Force', 'To force', 'A', 'the children 被迫在雨中踢球,被动 → Forced。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ as the best player of the match, she thanked her teammates.', 'Naming', 'Named', 'Name', 'To name', 'B', 'she 被评为最佳球员,被动 → Named。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), 'The trophy, ____ in gold, shone brightly under the stadium lights.', 'covering', 'cover', 'covered', 'to cover', 'C', 'the trophy 被镀金覆盖,被动/状态 → covered。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.02'), '____ by the referee''s whistle, the players stopped at once.', 'Stopping', 'Stop', 'To stop', 'Stopped', 'D', 'the players 被哨声叫停,被动 → Stopped。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ towards the goal, the striker took a powerful shot.', 'Running', 'Run', 'Run to', 'To running', 'A', '逻辑主语 the striker 主动 run → -ing,Running。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ by the fans, the tired players found new energy.', 'Cheering', 'Cheered', 'Cheer', 'To cheer', 'B', 'the players 被球迷欢呼鼓舞,被动 → Cheered。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ the ball forward, Jess headed for the penalty area.', 'Hit', 'Been hit', 'Hitting', 'To hit', 'C', 'Jess 主动 hit the ball → Hitting。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ from the high stand, the green pitch looked perfect.', 'Seeing', 'See', 'To see', 'Seen', 'D', 'the pitch 被(从看台)看,被动 → Seen。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ the whistle, the referee called full-time.', 'Blowing', 'Blown', 'Blow', 'To blow', 'A', 'the referee 主动 blow → Blowing。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ by a teammate, the injured player limped off the field.', 'Helping', 'Helped', 'Help', 'To help', 'B', 'the player 被队友扶,被动 → Helped。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ deeply, she tried to calm herself before the shot.', 'Breathed', 'Breathe', 'Breathing', 'To breathed', 'C', 'she 主动 breathe → Breathing。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ as the best athlete, Leo felt both proud and shy.', 'Choosing', 'Choose', 'To choose', 'Chosen', 'D', 'Leo 被选为最佳,被动 → Chosen。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ that the score was level, Joe gave the team a pep talk.', 'Knowing', 'Known', 'Know', 'To know', 'A', 'Joe 主动 know → Knowing。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ off the varsity team, the boy worked harder than ever.', 'Leaving', 'Left', 'Leave', 'To leave', 'B', 'the boy 被排除在队外,被动 → Left。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), 'The fans went wild, ____ loudly when the goal went in.', 'screamed', 'to scream', 'screaming', 'been screaming', 'C', 'the fans 主动 scream,伴随 → screaming。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ by his coach, the young player never gave up his dream.', 'Encouraging', 'Encourage', 'To encourage', 'Encouraged', 'D', 'the player 被教练鼓励,被动 → Encouraged。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ the ball into the corner, she rolled it past the keeper.', 'Guiding', 'Guided', 'Guide', 'To guide', 'A', 'she 主动 guide the ball → Guiding。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ in team colours, the spectators sang all through the match.', 'Dressing', 'Dressed', 'Dress', 'To dress', 'B', 'spectators 处于''穿着''状态,被动/状态 → Dressed。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ hard all season, the team felt ready for the final.', 'Having been trained', 'Trained', 'Having trained', 'To train', 'C', 'the team 主动完成训练 → 主动完成式 Having trained。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ by the loud roar, the new player almost missed his kick.', 'Surprising', 'Surprise', 'To surprise', 'Surprised', 'D', 'the player 被吼声惊到,被动 → Surprised。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), 'He placed the ball on the spot, ____ up at the goal.', 'looking', 'looked', 'to look', 'been looking', 'A', 'he 主动 look up,伴随 → looking。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ to take the final penalty, Jess walked over with heavy steps.', 'Asking', 'Asked', 'Ask', 'To ask', 'B', 'Jess 被要求/被叫上去,被动 → Asked。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ the ball away, the goalkeeper saved the team once more.', 'Punched', 'Punch', 'Punching', 'To punch', 'C', 'the goalkeeper 主动 punch the ball → Punching。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='required2' AND unit='U4' AND code='s2u4.03'), '____ in gold letters, the team''s name shone on the trophy.', 'Writing', 'Write', 'To write', 'Written', 'D', 'the name 被写,被动 → Written。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Boy Who Fell in Love with Basketball', 'When Michael Jordan was young, he was not always the best player on the court. At first he barely remembered the name of the game. Then, little by little, he began to study it. He lifted weights, did pull-ups and worked on his passing, dribbling and shooting again and again. His coach noticed that the boy was starting to fall in love with the sport. Coach Smith taught him not only how to play, but also how to listen to the game, how to respect it and how to appreciate it. One night, in the final seconds of an important championship game, Jordan took a famous shot that gave his team the win. For him, basketball became far more than just a ball, a court or a pair of sneakers. It was his dearest friend, his toughest competitor and his passport around the world. Even after his playing days were over, he said their relationship would never end.', 'Sports', 158, '[{"q":"What was Jordan like as a player at first?","answer":"A","options":["He was not yet the best and hardly knew the game.","He was already the greatest in the world.","He never touched a basketball.","He hated every kind of sport."],"explanation":"原文 ''not always the best'' 与 ''barely remembered the name'' 的转述。"},{"q":"What did Coach Smith teach Jordan besides playing?","answer":"B","options":["How to sell tickets.","To respect and appreciate the game.","How to coach other teams.","To give up when tired."],"explanation":"原文 ''how to respect it and how to appreciate it'' 的概括。"},{"q":"What did basketball finally mean to Jordan?","answer":"A","options":["Far more than a ball — a lifelong relationship.","Only a way to make money.","Just a simple childhood game.","Something he soon forgot."],"explanation":"末段 ''more than just a ball… relationship will never end'' 的转述。"}]'::jsonb, '[{"word":"competitor","cn":"对手;竞争者"},{"word":"title","cn":"冠军"},{"word":"appreciate","cn":"欣赏"}]'::jsonb, 2, 'required2', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Last Penalty', 'The friendly match between Jess''s team and the German side had ended in a draw, so the game would be decided by penalties. Jess hoped the match might be settled before her turn came, because her legs were shaking with nerves. One by one the players stepped up. The Germans scored, then Jules scored; the Germans scored again, then Mel scored. When Hannah rolled the ball smoothly into the corner of the net, everything came down to the last German kicker and to Jess. A loud roar around the stadium told Jess that the German player had scored, so she had to take her turn. With heavy steps she walked over and placed the ball on the spot. Behind her she could hear her teammates yelling encouragement. She took a deep breath, made a huge effort and ran towards the ball. But even as she hit it, she knew it was wrong. The ball struck the crossbar and bounced away into the crowd. Her team had lost, and she felt completely gutted.', 'Sports', 172, '[{"q":"Why was the game decided by penalties?","answer":"B","options":["Because the referee was angry.","Because the match had ended level.","Because one team left early.","Because it started to rain."],"explanation":"原文 ''ended in a draw, so… decided by penalties'' 的转述。"},{"q":"How did Jess feel before taking her kick?","answer":"C","options":["Relaxed and certain of success.","Bored and uninterested.","Nervous, with her legs shaking.","Angry at her teammates."],"explanation":"原文 ''legs were shaking with nerves'' 的概括。"},{"q":"What happened to Jess''s penalty?","answer":"D","options":["It rolled into the corner.","The keeper caught it easily.","It won the game for her team.","It hit the crossbar and went out."],"explanation":"原文 ''struck the crossbar and bounced away'' 的转述。"}]'::jsonb, '[{"word":"draw","cn":"平局"},{"word":"spot","cn":"(点球)点;位置"},{"word":"bounce","cn":"弹起"}]'::jsonb, 2, 'required2', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Leo''s Wushu Dream', 'Leo is a young wushu athlete who competes for the Finnish team. Wushu, also known as kung fu, is a Chinese sport. In competitive wushu, athletes perform a set of movements while judges give them points. Leo first got into the sport by watching Chinese kung fu films and admiring stars like Bruce Lee. He has been training for several years and has already won medals at different international championships. Now he wants to go as far as he can, taking part in the European and World Championships and one day, he hopes, the Olympic Games, if wushu is ever added to them. Still, Leo has to be realistic. The top competitors from China and a few other countries are full-time professionals who train for many hours every day. To reach that level, wushu in Finland would also need much more funding. Even so, Leo keeps practising hard, encouraged by his love for the sport.', 'Sports', 155, '[{"q":"How are points given in competitive wushu?","answer":"A","options":["By judges who watch the athletes'' movements.","By the size of the crowd.","By the fastest runner only.","By the team with most fans."],"explanation":"原文 ''judges give them points'' 的转述。"},{"q":"How did Leo first become interested in wushu?","answer":"B","options":["A friend forced him to join.","He watched kung fu films and admired stars.","He read about it in a textbook.","His school made it a subject."],"explanation":"原文 ''watching Chinese kung fu films and admiring stars'' 的转述。"},{"q":"Why does Leo say he must be realistic?","answer":"C","options":["Because he dislikes the sport now.","Because he has won no medals at all.","Because top rivals are full-time pros and funding is short.","Because wushu is too easy for him."],"explanation":"原文 ''professionals who train many hours… need much more funding'' 的概括。"}]'::jsonb, '[{"word":"judge","cn":"裁判员"},{"word":"realistic","cn":"现实的"},{"word":"professional","cn":"职业运动员"}]'::jsonb, 2, 'required2', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Why Team Sport Matters', 'Many people think that winning a match is all about one star player, but in team sports the truth is different. A single goal is often the result of many small actions. One player wins the ball, another passes it forward, and a third runs into space to score. If just one of them forgets the team and tries to do everything alone, the move usually breaks down. Good teams also support each other when things go wrong. When a player misses an easy chance, teammates do not shout at him; instead they encourage him to keep his head up and try again. Trust like this is built slowly through hours of training together. That is why a coach spends so much time helping players learn to read one another. In the end, a team that plays as one will often beat a group of talented players who think only about themselves. Sport, in this way, teaches a lesson that reaches far beyond the field.', 'Sports', 165, '[{"q":"According to the text, how is a goal usually scored in team sport?","answer":"D","options":["By one star doing everything alone.","Purely by luck.","Without any passing at all.","Through several players working together."],"explanation":"原文 ''the result of many small actions'' 的转述。"},{"q":"What do good teammates do when a player makes a mistake?","answer":"A","options":["They encourage him to try again.","They leave the field.","They shout angrily at him.","They stop the match."],"explanation":"原文 ''they encourage him to keep his head up'' 的转述。"},{"q":"What is the writer''s main point?","answer":"B","options":["Talent alone always wins.","Teamwork often beats selfish talent.","Coaches are not needed.","Winning does not matter at all."],"explanation":"末段 ''a team that plays as one will often beat… selfish'' 的概括。"}]'::jsonb, '[{"word":"pass","cn":"传球"},{"word":"encourage","cn":"鼓励"},{"word":"support","cn":"支持"}]'::jsonb, 2, 'required2', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Hours Behind the Title', 'When fans watch a champion lift the title, they see only a few wonderful minutes. What they do not see are the years of quiet, hard work behind that moment. Most top athletes train when it is still dark outside and most people are asleep. They repeat the same simple movements thousands of times until the body remembers them without thinking. They follow a careful plan for food, rest and exercise, and they keep going even when they feel exhausted or are slowed down by small injuries. Just as important is the mind. A good athlete learns to stay calm under pressure and to forget a mistake quickly so that it does not affect the next play. None of this looks exciting, and almost no one watches it happen. Yet it is exactly this hidden effort, repeated day after day, that turns an ordinary player into a champion. The title is only the small, bright tip of a very long story.', 'Sports', 161, '[{"q":"What do fans usually fail to see, according to the text?","answer":"C","options":["The final score of the match.","The colour of the team shirts.","The years of hard work behind a win.","The name of the stadium."],"explanation":"原文 ''years of quiet, hard work behind that moment'' 的转述。"},{"q":"Besides the body, what else must a top athlete train?","answer":"D","options":["Only the voice.","Nothing else at all.","Only their luck.","The mind, so as to keep cool when nervous."],"explanation":"原文 ''Just as important is the mind… stay calm under pressure'' 的转述(改写避免照抄)。"},{"q":"What does the writer mean by ''the small, bright tip of a very long story''?","answer":"A","options":["The visible victory rests on long hidden effort.","The title is the most important thing.","Winning takes no effort.","Stories should be kept short."],"explanation":"末句以 ''hidden effort… turns an ordinary player into a champion'' 作铺垫的概括。"}]'::jsonb, '[{"word":"exhausted","cn":"筋疲力尽的"},{"word":"calm","cn":"镇静的"},{"word":"effort","cn":"努力"}]'::jsonb, 2, 'required2', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Why We Love to Play', 'Why do so many people give up their free time to chase a ball around a field? Different players would give different answers. For some, the main pull is the feeling of complete engagement, those moments when time seems to disappear and nothing exists except the game. For others, sport is mostly about friendship: the shared jokes in the changing room and the people you hang out with after every match. Many enjoy the challenge of slowly getting better and beating their own past record. There is also the simple joy of moving, of running fast and feeling strong and alive. Of course, sport has its hard side too. There is the stress before a big game, the pain of an injury, and the disappointment of losing after weeks of effort. Yet most players agree that the good far outweighs the bad. They keep coming back, week after week, because for them a life with sport is simply richer than a life without it.', 'Sports', 164, '[{"q":"What is one reason the writer gives for loving sport?","answer":"B","options":["The chance to earn lots of money.","The feeling of being fully engaged in the game.","Getting out of all school work.","Never having to train."],"explanation":"原文 ''feeling of complete engagement'' 的转述。"},{"q":"Why do some players value sport, according to the text?","answer":"C","options":["Because it has no difficulties.","Because they dislike moving.","Because of the friendships it builds.","Because it is always easy to win."],"explanation":"原文 ''sport is mostly about friendship'' 的转述。"},{"q":"What does the writer admit about sport?","answer":"D","options":["It brings only joy.","It costs nothing at all.","No one ever loses.","It also has stress, injury and disappointment."],"explanation":"原文 ''sport has its hard side too… stress… injury… disappointment'' 的转述。"}]'::jsonb, '[{"word":"hang out","cn":"(常)一起消磨时间"},{"word":"challenge","cn":"挑战"},{"word":"stress","cn":"压力"}]'::jsonb, 2, 'required2', 'U4', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'My First Match', 'I will never forget my first football (1)____. My legs were shaking as I ran onto the green (2)____. The home (3)____ was huge, and I could hear thousands of fans cheering. In the first half, our team played well, but neither side could (4)____ a goal. During the break, the (5)____ gave us a short pep talk and told us to stay (6)____. In the second half, a teammate (7)____ the ball forward to me. I took a deep (8)____, ran towards the goal and kicked the ball hard. It flew straight into the (9)____! The whole team began to (10)____ with joy. That day I learned that sport is not only about winning, but also about playing together.', 120, 2, '[{"q":"1","answer":"A","options":["match","song","price","machine"],"explanation":"football match 足球比赛。"},{"q":"2","answer":"B","options":["shop","pitch","menu","book"],"explanation":"the green pitch 绿茵场。"},{"q":"3","answer":"C","options":["garden","kitchen","stadium","market"],"explanation":"the home stadium 主场体育场。"},{"q":"4","answer":"D","options":["sell","eat","buy","score"],"explanation":"score a goal 进球。"},{"q":"5","answer":"A","options":["coach","driver","waiter","doctor"],"explanation":"the coach 教练。"},{"q":"6","answer":"B","options":["angry","calm","hungry","late"],"explanation":"stay calm 保持镇静。"},{"q":"7","answer":"C","options":["sold","ate","passed","lost"],"explanation":"passed the ball 把球传过来。"},{"q":"8","answer":"D","options":["price","noise","song","breath"],"explanation":"take a deep breath 深吸一口气。"},{"q":"9","answer":"A","options":["net","wall","river","tree"],"explanation":"into the net 进入球网。"},{"q":"10","answer":"B","options":["cry","scream","sleep","leave"],"explanation":"scream with joy 欢呼尖叫。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'A Goalkeeper''s Day', 'Being a (1)____ is one of the hardest jobs on a football team. While other players run and attack, the keeper must (2)____ the goal alone. During a match, he often stands and waits, watching the (3)____ move around the field. Then, in a single second, he must dive to (4)____ a fast shot. One small mistake can let the other team (5)____, so he can never lose his (6)____. After the game, the keeper is often (7)____, even though he has run less than the others. People sometimes forget how much (8)____ it takes to do this job well. A great keeper trains every (9)____, practising the same movements again and again. When he makes a wonderful save, the whole (10)____ jumps up and cheers his name.', 128, 2, '[{"q":"1","answer":"C","options":["teacher","farmer","goalkeeper","singer"],"explanation":"a goalkeeper 守门员。"},{"q":"2","answer":"D","options":["sell","draw","open","defend"],"explanation":"defend the goal 防守球门。"},{"q":"3","answer":"A","options":["ball","prices","songs","noises"],"explanation":"the ball move 球的移动。"},{"q":"4","answer":"B","options":["eat","stop","buy","lose"],"explanation":"stop a shot 扑住射门。"},{"q":"5","answer":"C","options":["sleep","cry","score","leave"],"explanation":"let the other team score 让对方得分。"},{"q":"6","answer":"D","options":["money","ticket","hat","focus"],"explanation":"lose his focus 失去专注。"},{"q":"7","answer":"A","options":["exhausted","happy only","rich","free"],"explanation":"exhausted 筋疲力尽的。"},{"q":"8","answer":"B","options":["price","effort","noise","song"],"explanation":"how much effort 多少努力。"},{"q":"9","answer":"C","options":["year","century","day","never"],"explanation":"every day 每天。"},{"q":"10","answer":"D","options":["garden","kitchen","shop","crowd"],"explanation":"the crowd jumps up 观众跳起来。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'The Joy of Running', 'I started (1)____ three years ago, and now I cannot imagine life without it. At first it was a real (2)____, and after only a few minutes I was out of (3)____. But slowly my body grew (4)____, and the runs became easier. Now, early every morning, I put on my shoes and head out before the city wakes up. As I run, my (5)____ clears and my worries seem to disappear. Running is also a cheap sport: you do not need a big (6)____ or special equipment, only an open road. Sometimes I (7)____ a small goal, such as beating my own time, and that keeps me going. When I finally reach home, tired but happy, I feel (8)____ of myself. Running has taught me that you do not need to (9)____ anyone else; the only person you really compete with is the one you were (10)____.', 148, 2, '[{"q":"1","answer":"A","options":["running","selling","sleeping","crying"],"explanation":"started running 开始跑步。"},{"q":"2","answer":"B","options":["holiday","struggle","joke","song"],"explanation":"a real struggle 一种艰难。"},{"q":"3","answer":"C","options":["money","time","breath","luck"],"explanation":"out of breath 上气不接下气。"},{"q":"4","answer":"D","options":["weaker","smaller","shorter","stronger"],"explanation":"grew stronger 变得更强壮。"},{"q":"5","answer":"A","options":["mind","price","noise","ticket"],"explanation":"my mind clears 头脑变清醒。"},{"q":"6","answer":"B","options":["song","stadium","price","noise"],"explanation":"a big stadium 大型场馆。"},{"q":"7","answer":"C","options":["lose","sell","set","drop"],"explanation":"set a small goal 定个小目标。"},{"q":"8","answer":"D","options":["afraid","sorry","bored","proud"],"explanation":"feel proud 感到自豪。"},{"q":"9","answer":"A","options":["beat","help","thank","meet"],"explanation":"beat anyone else 击败别人。"},{"q":"10","answer":"B","options":["selling","yesterday","buying","eating"],"explanation":"the one you were yesterday 昨天的自己。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'Learning to Shoot', 'When I joined the school basketball team, my biggest (1)____ was shooting. I could run and pass, but my shots almost never (2)____ in. My coach told me not to give (3)____, and to practise a little every day. So each afternoon I stayed behind to (4)____ on my shooting. I learned to (5)____ my knees, look up at the basket, and let the ball (6)____ softly off my fingers. Slowly my hands began to (7)____ the right movement without thinking. After a few months, I made my first winning shot, and my teammates (8)____ with joy. That day I (9)____ that real skill comes only from hours of quiet practice. Now, whenever a younger player feels like quitting, I (10)____ him to keep trying, just as my coach once did for me.', 133, 2, '[{"q":"1","answer":"C","options":["song","price","problem","garden"],"explanation":"my biggest problem 最大难题。"},{"q":"2","answer":"D","options":["slept","sold","ate","went"],"explanation":"went in 投进。"},{"q":"3","answer":"A","options":["up","in","off","out"],"explanation":"give up 放弃。"},{"q":"4","answer":"B","options":["sell","work","lose","hide"],"explanation":"work on my shooting 改进投篮。"},{"q":"5","answer":"C","options":["sell","throw","bend","lose"],"explanation":"bend my knees 弯曲膝盖。"},{"q":"6","answer":"D","options":["sleep","cry","leave","roll"],"explanation":"roll off my fingers 从指尖滚出。"},{"q":"7","answer":"A","options":["remember","sell","lose","throw"],"explanation":"remember the movement 记住动作。"},{"q":"8","answer":"B","options":["slept","screamed","cried","left"],"explanation":"screamed with joy 欢呼。"},{"q":"9","answer":"C","options":["forgot","sold","learned","lost"],"explanation":"I learned 我明白了。"},{"q":"10","answer":"D","options":["sell","leave","forget","encourage"],"explanation":"encourage him 鼓励他。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'Before the Big Game', 'The night before an important (1)____, almost every athlete feels (2)____. Even great players say their hearts beat fast and their hands feel cold. The (3)____ of letting the team down can be hard to bear. But there are ways to (4)____ yourself down. Many players take slow, deep (5)____ and picture the match going well in their (6)____. A good coach also gives a short pep talk to (7)____ the team. He reminds them of all the hours they have (8)____ together and tells them to trust each other. Once the (9)____ blows the whistle and the game begins, most of the fear disappears. The players stop worrying and simply (10)____ on the ball. In the end, learning to deal with pressure is just as important as any other skill in sport.', 133, 2, '[{"q":"1","answer":"A","options":["match","song","price","shop"],"explanation":"an important match 重要比赛。"},{"q":"2","answer":"B","options":["bored","nervous","hungry","free"],"explanation":"feel nervous 感到紧张。"},{"q":"3","answer":"C","options":["price","noise","fear","song"],"explanation":"the fear of 害怕……。"},{"q":"4","answer":"D","options":["sell","lose","hide","calm"],"explanation":"calm yourself down 让自己平静。"},{"q":"5","answer":"A","options":["breaths","prices","songs","noises"],"explanation":"deep breaths 深呼吸。"},{"q":"6","answer":"B","options":["pockets","minds","shoes","bags"],"explanation":"in their minds 在脑海中。"},{"q":"7","answer":"C","options":["sell","leave","encourage","forget"],"explanation":"encourage the team 鼓励球队。"},{"q":"8","answer":"D","options":["sold","lost","left","trained"],"explanation":"hours they have trained 一起训练的时间。"},{"q":"9","answer":"A","options":["referee","driver","waiter","farmer"],"explanation":"the referee blows the whistle 裁判吹哨。"},{"q":"10","answer":"B","options":["sleep","focus","cry","leave"],"explanation":"focus on the ball 专注于球。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'Cheering for the Home Team', 'On match day, our small town comes alive. Thousands of (1)____ wear the team''s colours and walk towards the (2)____. Inside, the noise is incredible: people sing, shout and wave flags to (3)____ the home team. When our side scores, a huge (4)____ goes up around the ground, and strangers hug each other like old friends. Even when we are (5)____, the fans do not stop cheering; they believe their voices can help the players (6)____ harder. After the final (7)____, win or lose, everyone walks home together, still talking about the best (8)____ of the day. Watching live sport is very different from watching it on a screen at home. You can feel the (9)____ all around you, and for ninety minutes nothing else seems to matter. That shared feeling is one big (10)____ why so many people love going to the match.', 144, 2, '[{"q":"1","answer":"C","options":["prices","songs","fans","machines"],"explanation":"thousands of fans 数千球迷。"},{"q":"2","answer":"D","options":["kitchen","market","garden","stadium"],"explanation":"towards the stadium 走向体育场。"},{"q":"3","answer":"A","options":["support","sell","leave","forget"],"explanation":"support the home team 支持主队。"},{"q":"4","answer":"B","options":["price","roar","song","noise"],"explanation":"a huge roar 巨大的轰鸣。"},{"q":"5","answer":"C","options":["selling","sleeping","losing","eating"],"explanation":"even when we are losing 即便落后。"},{"q":"6","answer":"D","options":["sleep","cry","leave","fight"],"explanation":"fight harder 更努力拼搏。"},{"q":"7","answer":"A","options":["whistle","price","noise","song"],"explanation":"the final whistle 终场哨。"},{"q":"8","answer":"B","options":["sleep","moments","price","noise"],"explanation":"the best moments 最美好的时刻。"},{"q":"9","answer":"C","options":["price","machine","energy","garden"],"explanation":"feel the energy 感受到那股气氛。"},{"q":"10","answer":"D","options":["price","noise","shop","reason"],"explanation":"one big reason why 一个重要原因。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Which Sport to Try', '上外版必修第二册 U4 · dialogue', 3, 'Mia: The school sports club is looking for new members. Which sport will you try, Tom?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·短文 Why Sport Is Good for Us', '上外版必修第二册 U4 · passage', 2, 'Doing sport is good for both the body and the mind.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Before the Penalties', '上外版必修第二册 U4 · dialogue', 3, 'Coach Joe: The match ended in a draw, so we go to penalties. Stay calm, everyone.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·短文 The Hours Behind a Champion', '上外版必修第二册 U4 · passage', 2, 'When we watch a champion win a title, we see only a few bright minutes.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 A Fan at the Match', '上外版必修第二册 U4 · dialogue', 3, 'Liam: This is my first time watching live football. The stadium is huge!
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·短文 A Tip for New Players', '上外版必修第二册 U4 · passage', 2, 'Here is a simple tip for anyone who is new to a sport.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write a "Letter to a Sport"(给一项运动写一封信)', 'Write a "Letter to a Sport"(给一项运动写一封信)', '请仿照乔丹《写给篮球的公开情书》,给一项你喜欢(或曾经讨厌)的运动写一封约80词的信。内容包括:① 你第一次接触这项运动的情形;② 中间经历的一个困难或转折;③ 现在你对它的感受。要求按时间顺序展开,语言真挚。', 'Following Michael Jordan''s "Open Love Letter to Basketball", write a letter (about 80 words) to a sport you love (or once disliked). Include: 1) how you first met the sport; 2) one difficulty or turning point along the way; 3) how you feel about it now. Write in chronological order with honest feeling.', '["开头点明对象与初遇(Dear Football, I still remember the day …)","中段写一个困难/转折(At first … but then …)","结尾写现在的感受(Now you are more than just a game to me.)","按时间顺序、用第二人称''you''称呼这项运动"]'::jsonb, 70, 100, 'Dear Football, I still remember the day we first met. I was eight, and a kind PE teacher took me onto the field. At first you felt strange to me; I kept missing the ball, and I almost wanted to give up. But slowly, training hard every week, I began to fall in love with you. You taught me to stay calm under pressure and to trust my teammates. Now you are far more than just a game; you are my dearest friend. I will always love you.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["I still remember the day we first met.","Training hard every week, I began to fall in love with you.","You taught me to stay calm under pressure and to trust my teammates.","Now you are far more than just a game; you are my dearest friend."]'::jsonb, '[{"wrong":"Train hard every week, I began to love you.","correct":"Training hard every week, I began to love you.","note":"逻辑主语 I 主动 train,作状语用 -ing 形式 Training。"},{"wrong":"Encouraging by my coach, I never gave up.","correct":"Encouraged by my coach, I never gave up.","note":"I 被教练鼓励,被动 → -ed 形式 Encouraged。"},{"wrong":"I almost wanted to gave up.","correct":"I almost wanted to give up.","note":"want to 后接动词原形 give。"}]'::jsonb, '【给运动的信结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required2', 'U4', '{"title":"-ing / -ed 形式作状语·主被动速查","intro":"分词作状语表时间/原因/结果/伴随。判断口诀:逻辑主语(=主句主语)主动发出动作→ -ing;承受动作或处于被动状态→ -ed。Running fast, he won.(主动)/ Encouraged by fans, he played on.(被动)","table":{"headers":["形式","用法 / 例句"],"rows":[["-ing(主动)","主语主动做:Hearing the whistle, the players stopped.(听到=主动)"],["-ed(被动)","主语被…:Beaten in the final, the team felt sad.(被打败)"],["Having + done(主动完成)","动作先于主句且主动:Having trained hard, she won the title."],["逻辑主语一致","分词的逻辑主语必须就是主句主语:Running fast, HE won.(不是 the ball)"]]},"specialRules":[{"rule":"主语主动发出动作 → 用 -ing","mark":"Running towards the goal, he shot.(他主动跑)"},{"rule":"主语承受动作 / 被动 → 用 -ed","mark":"Encouraged by the coach, he played on.(他被鼓励)"},{"rule":"分词逻辑主语 = 主句主语,否则就是错句(垂悬分词)","mark":"Seen from the stand, the players looked tiny.(被看的是 players)"},{"rule":"动作先于主句且主动 → 用 Having done","mark":"Having scored, she ran to her teammates."}],"why":["-ing 表''主动/正在'',-ed 表''被动/已完成受动''。先找出分词的逻辑主语(几乎总是主句主语),再问:这个主语是''做''这个动作,还是''被''这个动作?做→-ing,被→-ed。"],"gaokaoPoints":["语法填空高频:给出动词原形,据主语主被动填 -ing 或 -ed。","辨析重点:主语与分词动作的主被动关系;垂悬分词(逻辑主语不一致)是常见错误。"],"examVsReal":[{"exam":"Encouraged by his coach, he kept going.(书面/考试)","real":"His coach encouraged him, so he kept going.","note":"考试爱考分词状语;口语里常直接用并列句或 because 从句,更直白"},{"exam":"Running fast, he reached the line first.(考试)","real":"He ran fast and reached the line first.","note":"考试用 -ing 状语;日常口语更常用并列动词"}]}'::jsonb, 'sufe');
